export function calculateAnnualLoad(projects: Project[], teamRoster: TeamMember[] = []): WriterLoad[] {
  const writers: Record<string, WriterLoad> = {};

  teamRoster.forEach((member) => {
    writers[member.id] = {
      ...member,
      projects: [],
      totalHours: 0,
      committedHours: 0,
      annualCapacity: member.weeklyCapacity * 48,
    };
  });

  projects.forEach((project) => {
    const writer = writers[project.assignedTo];
    if (!writer) return;

    let hours = 0;
    if (project.manualHours) {
      hours = project.manualHours;
    } else {
      const raw = project.targetWords / (writer.draftSpeed || 200);
      hours = raw * (1 + writer.chaosBuffer / 100);
    }

    writer.projects.push({ ...project, calculatedHours: hours });
    writer.totalHours += hours;

    if (project.lifecycleState === "Production") {
      if (project.tasks && project.tasks.length > 0) {
        project.tasks.forEach((t) => {
          if ((t.status === "Active" || t.status === "Review") && t.remainingHours > 0) {
            const assignee = writers[t.assigneeId];
            if (assignee) {
              assignee.committedHours += t.remainingHours;
            }
          }
        });
      } else {
        writer.committedHours += hours;
      }
    }
  });

  return Object.values(writers);
}

export function calculateProjectAnalysis(
  projects: Project[],
  metrics: Metrics = DEFAULT_METRICS
): ProjectAnalysis[] {
  return projects.map((project) => {
    let total = 0;
    let estCost = 0;

    if (project.manualHours) {
      estCost = project.manualHours * metrics.blendedHourlyRate;
      total = project.manualHours;
    } else {
      const writing = (project.targetWords / 1000) * metrics.writingRate;
      const pages = project.targetWords / metrics.wordsPerPage;
      const layout = pages * metrics.layoutHoursPerPage;
      const coreWork = project.internalStatus === "Layout" ? layout : writing + layout;
      const pm = coreWork * metrics.pmOverheadPercent;
      const subtotal = coreWork + pm;
      const contingency = subtotal * metrics.contingencyPercent;
      total = Math.round(subtotal + contingency);
      estCost = total * metrics.blendedHourlyRate;
    }

    // Calculate Committed Cost (Execution Boundary)
    let committedCost = 0;
    if (project.lifecycleState === "Production") {
      let activeHours = 0;
      if (project.tasks && project.tasks.length > 0) {
        activeHours = project.tasks
          .filter(t => (t.status === "Active" || t.status === "Review") && t.remainingHours > 0)
          .reduce((sum, t) => sum + t.remainingHours, 0);
      } else {
        // Fallback: If in Production but no tasks, assume total estimate is active
        activeHours = total;
      }
      // Apply contingency to remaining work
      const contingency = activeHours * metrics.contingencyPercent;
      committedCost = (activeHours + contingency) * metrics.blendedHourlyRate;
    }

    return { ...project, total, estCost, committedCost };
  });
}

export function calculateStakeholderDemand(
  analysis: ProjectAnalysis[]
): StakeholderDemand[] {
  const load: Record<string, number> = { Martin: 0, Matthew: 0, Dan: 0 };

  analysis.forEach((project) => {
    load[project.stakeholder] += project.total;
  });

  const labelMap: Record<string, { internal: string; client: string }> = {
    Martin: { internal: "Martin's Demand", client: "A-Series Initiative" },
    Matthew: { internal: "Matthew's Demand", client: "Eldritch Initiative" },
    Dan: { internal: "Dan (Architecture)", client: "Production Engine" },
  };

  return Object.entries(load).map(([stakeholderKey, hours]) => {
    const key = stakeholderKey as Stakeholder;
    return {
      stakeholder: key,
      internalLabel: labelMap[stakeholderKey]?.internal ?? stakeholderKey,
      clientLabel: labelMap[stakeholderKey]?.client ?? stakeholderKey,
      hours,
      fill: STAKEHOLDER_COLORS[key],
    };
  });
}

export function bucketByQuarter(analysis: ProjectAnalysis[]): QuarterBuckets {
  return analysis.reduce<QuarterBuckets>((acc, project) => {
    if (!acc[project.launchWindow]) {
      acc[project.launchWindow] = [];
    }
    acc[project.launchWindow].push(project);
    return acc;
  }, {});
}

export function calculateDefenseAnalysis(
  defendHourlyRate: number,
  defendWPH: number,
  marketPerWord: number,
  annualWords = 200_000
): DefenseAnalysisResult {
  const myCostPerWord = defendHourlyRate / defendWPH;
  const savingsPerWord = marketPerWord - myCostPerWord;
  const savingsPercent = (savingsPerWord / marketPerWord) * 100;
  const marketCost = annualWords * marketPerWord;
  const myCost = annualWords * myCostPerWord;

  return { myCostPerWord, savingsPerWord, savingsPercent, marketCost, myCost };
}

export function buildScenarioRows(
  scenarios: IncomeScenario[],
  wordRate: number,
  capacityWordsPerYear: number
): ScenarioRow[] {
  return scenarios.map((scenario) => {
    const wordsNeeded = wordRate > 0 ? scenario.desiredIncome / wordRate : 0;
    const feasible = capacityWordsPerYear >= wordsNeeded;
    return { ...scenario, wordsNeeded, feasible };
  });
}

export function computeEffectiveWords(totalWords: number, existingWords: number = 0): number {
  return Math.max(0, totalWords - existingWords);
}

export function todayISO(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = `${now.getMonth() + 1}`.padStart(2, "0");
  const day = `${now.getDate()}`.padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function addWorkingDays(startISO: string, days: number, includeWeekends: boolean): string {
  if (!startISO) return "";

  const [y, m, d] = startISO.split("-").map((part) => parseInt(part, 10));
  if (!y || !m || !d) return startISO;

  // Use UTC at midday to avoid DST/offset drift
  const date = new Date(Date.UTC(y, m - 1, d, 12, 0, 0));

  if (days <= 0) {
    return date.toISOString().slice(0, 10);
  }

  let remaining = Math.ceil(days);
  while (remaining > 0) {
    date.setUTCDate(date.getUTCDate() + 1);
    const dayOfWeek = date.getUTCDay();
    if (includeWeekends || (dayOfWeek !== 0 && dayOfWeek !== 6)) {
      remaining -= 1;
    }
  }

  return date.toISOString().slice(0, 10);
}

export function computePaceScenario({
  effectiveWords,
  speed,
  chaosPercent,
  pacingMode,
  dailyHours,
  weeklyHours,
  includeWeekends,
  startDate,
}: {
  effectiveWords: number;
  speed: number;
  chaosPercent: number;
  pacingMode: "daily" | "weekly";
  dailyHours: number;
  weeklyHours?: number;
  includeWeekends: boolean;
  startDate: string;
}): PaceScenario {
  if (effectiveWords <= 0 || speed <= 0) {
    return {
      hours: 0,
      days: 0,
      finishDate: startDate || todayISO(),
    };
  }

  const chaosMult = 1 + (chaosPercent || 0) / 100;
  const rawHours = (effectiveWords / speed) * chaosMult;

  let hoursPerDay: number;
  if (pacingMode === "daily") {
    hoursPerDay = dailyHours > 0 ? dailyHours : 1;
  } else {
    const weekly = weeklyHours && weeklyHours > 0 ? weeklyHours : dailyHours * 5;
    hoursPerDay = weekly / 7;
  }

  const rawDays = hoursPerDay > 0 ? rawHours / hoursPerDay : 0;
  const roundedHours = Math.round(rawHours);
  const roundedDays = Math.ceil(rawDays);
  const finishDate = addWorkingDays(startDate || todayISO(), rawDays, includeWeekends);

  return {
    hours: roundedHours,
    days: roundedDays,
    finishDate,
  };
}

export function getDefaultDraftSpeedForRole(roleId?: string | null): number {
  if (!roleId) return 175;
  const key = roleId.toLowerCase();
  if (key === "dan" || key === "dan-cross") return 200;
  if (key === "martin") return 150;
  return 175;
}

export function runEstimatorV2(
  input: EstimatorInputV2,
  teamRoster: TeamMember[] = []
): EstimatorOutputV2 {
  const effectiveWords = computeEffectiveWords(input.totalWords, input.existingWords ?? 0);

  const pacingMode = input.pacingMode || "daily";
  const baseStart = input.startDate || todayISO();

  const member = input.roleId
    ? teamRoster.find((m) => m.id === input.roleId)
    : undefined;

  const draftSpeed =
    input.draftSpeed || member?.draftSpeed || getDefaultDraftSpeedForRole(input.roleId);

  const compileSpeed =
    input.compileSpeed || member?.compileSpeed || 0;

  const chaosPercent =
    input.bufferPercent ?? (member?.chaosBuffer ?? 0);

  const draftScenario = computePaceScenario({
    effectiveWords,
    speed: draftSpeed,
    chaosPercent,
    pacingMode,
    dailyHours: input.dailyHours,
    weeklyHours: input.weeklyHours,
    includeWeekends: input.includeWeekends,
    startDate: baseStart,
  });

  const compileScenario = compileSpeed > 0
    ? computePaceScenario({
        effectiveWords,
        speed: compileSpeed,
        chaosPercent,
        pacingMode,
        dailyHours: input.dailyHours,
        weeklyHours: input.weeklyHours,
        includeWeekends: input.includeWeekends,
        startDate: baseStart,
      })
    : {
        hours: 0,
        days: 0,
        finishDate: baseStart,
      };

  const managerParts: string[] = [];
  managerParts.push(
    `"${input.activity}" at ${Math.round(draftSpeed)} w/hr with ${chaosPercent}% buffer and ${input.dailyHours} hrs/day is about ${draftScenario.hours} hours (${draftScenario.days} working days), finishing around ${draftScenario.finishDate}.`
  );

  if (compileSpeed > 0 && compileScenario.hours > 0) {
    managerParts.push(
      `With compile support at ${Math.round(compileSpeed)} w/hr, full draft+compile time is about ${compileScenario.hours} hours (${compileScenario.days} days), finishing around ${compileScenario.finishDate}.`
    );
  }

  const managerText = managerParts.join(" ");

  const selfText = [
    `Effective words: ${effectiveWords.toLocaleString()}.`,
    `Draft-only: ${draftScenario.hours}h over ${draftScenario.days} day(s), finish ${draftScenario.finishDate}.`,
    compileSpeed > 0 && compileScenario.hours > 0
      ? `Draft+compile: ${compileScenario.hours}h over ${compileScenario.days} day(s), finish ${compileScenario.finishDate}.`
      : `No compile speed configured; draft-only scenario is primary.`,
  ].join(" ");

  return {
    effectiveWords,
    draftScenario,
    compileScenario,
    managerText,
    selfText,
  };
}

export function runEstimator(
  input: EstimatorInput,
  teamRoster: TeamMember[] = []
): EstimatorResult {
  const mapped: EstimatorInputV2 = {
    activity: input.activity,
    totalWords: input.totalWords,
    existingWords: 0,
    draftSpeed: input.draftSpeed,
    compileSpeed: 0,
    bufferPercent: input.bufferPercent,
    pacingMode: "daily",
    dailyHours: input.dailyHours,
    weeklyHours: undefined,
    includeWeekends: true,
    startDate: todayISO(),
    roleId: input.teamMemberId,
  };

  const v2 = runEstimatorV2(mapped, teamRoster);

  const hours = v2.draftScenario.hours;
  const days = v2.draftScenario.days;
  const date = v2.draftScenario.finishDate;

  const teamMember = input.teamMemberId
    ? teamRoster.find((m) => m.id === input.teamMemberId)
    : undefined;

  const mgrText = v2.managerText;

  return {
    hours,
    days,
    date,
    mgrText,
    teamMember,
    roleAdjusted: false,
  };
}

export interface ProjectArtEstimate {
  regionalMaps: number;
  encounterMaps: number;
  interiorIllustrations: number;
  spotArt: number;
  npcPortraits: number;
  covers: number;
  totalPieces: number;
  regionalMapCost: number;
  encounterMapCost: number;
  interiorCost: number;
  spotCost: number;
  portraitCost: number;
  coverCost: number;
  totalCost: number;
  projectType: string;
  wordCount: number;
  multiplier: number;
  marketPreset: ArtDensityPreset;
  marketLabel: string;
}

/**
 * Estimate art needs for a project based on word count, project type, and market target.
 * 
 * Market Presets:
 * - "osr" (default): A1 baseline, ~1 piece per 4,200 words, 23 pieces for 97k words
 * - "5e": WotC standard, ~1 piece per 3,000 words, 32-38 pieces for 97k words (+50% budget)
 * - "pathfinder": Paizo premium, ~1 piece per 1,600 words, 50-70 pieces for 97k words (+150% budget)
 * 
 * @param wordCount - Total word count of the project
 * @param projectType - Type of project (e.g., "Large Adventure", "Player Sourcebook")
 * @param marketPreset - Target market aesthetic ("osr", "5e", "pathfinder")
 */
export function estimateProjectArt(
  wordCount: number,
  projectType: string = "Large Adventure",
  marketPreset: ArtDensityPreset = "osr"
): ProjectArtEstimate {
  const density = ART_DENSITY_PRESETS[marketPreset];
  const typeMultiplier = PROJECT_TYPE_ART_MULTIPLIERS[projectType] ?? 1.0;
  
  // Fixed assets (per book, scaled by density preset)
  const regionalMaps = density.regionalMapsPerBook;
  const covers = density.coversPerBook;
  
  // Variable assets scaled by word count, project type, and market density
  const encounterMaps = Math.max(1, Math.round(wordCount * density.encounterMapsPerWord * typeMultiplier));
  const interiorIllustrations = Math.max(1, Math.round(wordCount * density.illustrationsPerWord * typeMultiplier));
  const spotArt = Math.max(1, Math.round(wordCount * density.spotArtPerWord * typeMultiplier));
  const npcPortraits = Math.max(0, Math.round(wordCount * density.portraitsPerWord * typeMultiplier));
  
  const totalPieces = regionalMaps + encounterMaps + interiorIllustrations + spotArt + npcPortraits + covers;
  
  // Calculate costs
  const regionalMapCost = regionalMaps * REGIONAL_MAP_DEFAULT;
  const encounterMapCost = encounterMaps * ENCOUNTER_MAP_DEFAULT;
  const interiorCost = interiorIllustrations * INTERIOR_FULL_DEFAULT;
  const spotCost = spotArt * INTERIOR_SPOT_DEFAULT;
  const portraitCost = npcPortraits * PORTRAIT_DEFAULT;
  const coverCost = covers * COVER_ART_RATE_DEFAULT;
  const totalCost = regionalMapCost + encounterMapCost + interiorCost + spotCost + portraitCost + coverCost;
  
  return {
    regionalMaps,
    encounterMaps,
    interiorIllustrations,
    spotArt,
    npcPortraits,
    covers,
    totalPieces,
    regionalMapCost,
    encounterMapCost,
    interiorCost,
    spotCost,
    portraitCost,
    coverCost,
    totalCost,
    projectType,
    wordCount,
    multiplier: typeMultiplier,
    marketPreset,
    marketLabel: density.label,
  };
}

export function runArtBudget(input: ArtModuleInput): ArtBudgetBreakdown {
  const safe = (n: number | undefined | null): number => (n && n > 0 ? n : 0);

  const numCovers = safe(input.numCovers);
  const numSpots = safe(input.numSpots);
  const numHalf = safe(input.numHalfPage);
  const numFull = safe(input.numFullPage);
  const numPortraits = safe(input.numPortraits);
  const numRegionalMaps = safe(input.numRegionalMaps);
  const numEncounterMaps = safe(input.numEncounterMaps);

  const coverCost = numCovers * COVER_ART_RATE_DEFAULT;
  const spotCost = numSpots * INTERIOR_SPOT_DEFAULT;
  const halfPageCost = numHalf * INTERIOR_HALF_DEFAULT;
  const fullPageCost = numFull * INTERIOR_FULL_DEFAULT;
  const portraitCost = numPortraits * PORTRAIT_DEFAULT;
  const regionalMapCost = numRegionalMaps * REGIONAL_MAP_DEFAULT;
  const encounterMapCost = numEncounterMaps * ENCOUNTER_MAP_DEFAULT;

  const totalArtCost = coverCost + spotCost + halfPageCost + fullPageCost + portraitCost + regionalMapCost + encounterMapCost;

  return {
    coverCost,
    spotCost,
    halfPageCost,
    fullPageCost,
    portraitCost,
    regionalMapCost,
    encounterMapCost,
    totalArtCost,
  };
}

export function calculateRoi(
  devCost: number,
  printRun: PrintRunConfig,
  pricing: ProductPricing,
  channel: DistributionChannel
): RoiResult {
  const quantity = Math.max(0, printRun.quantity || 0);
  const msrp = Math.max(0, pricing.msrp || 0);

  if (quantity === 0 || msrp === 0) {
    return {
      channelId: channel.id,
      netRevenuePerUnit: 0,
      totalRevenue: 0,
      totalCogs: 0,
      grossMargin: 0,
      netProfit: -devCost,
      breakEvenUnits: devCost > 0 ? Number.POSITIVE_INFINITY : 0,
      roiPercent: 0,
    };
  }

  const discountMult = 1 - (channel.discountPercent || 0) / 100;
  const platformFeeMult = (channel.platformFeePercent || 0) / 100;

  const grossPerUnit = msrp * discountMult;
  const platformFeePerUnit = grossPerUnit * platformFeeMult;

  const tariffMult = 1 + (printRun.tariffPercent || 0) / 100;
  const printAndFreightPerUnit =
    (printRun.unitCost || 0) * tariffMult +
    (printRun.freightPerUnit || 0) +
    (printRun.warehousingPerUnit || 0);

  const fulfillmentPerUnit = channel.fulfillmentFeePerUnit || 0;

  const cogsPerUnit = printAndFreightPerUnit + fulfillmentPerUnit + platformFeePerUnit;
  const netRevenuePerUnit = grossPerUnit - cogsPerUnit;

  const totalRevenue = grossPerUnit * quantity;
  const totalCogs = cogsPerUnit * quantity;
  const grossMargin = totalRevenue - totalCogs;
  const netProfit = grossMargin - devCost;

  const breakEvenUnits = netRevenuePerUnit > 0 ? Math.ceil(devCost / netRevenuePerUnit) : Number.POSITIVE_INFINITY;
  const roiPercent = devCost > 0 ? (netProfit / devCost) * 100 : 0;

  return {
    channelId: channel.id,
    netRevenuePerUnit,
    totalRevenue,
    totalCogs,
    grossMargin,
    netProfit,
    breakEvenUnits,
    roiPercent,
  };
}
